def rle(s):
    if not s:
        return ''

    result = []
    current_char = s[0]
    count = 1

    for char in s[1:]:
        if char == current_char:
            count += 1
        else:
            result.append(f"{current_char}{count}")
            current_char = char
            count = 1

    # Append the last group
    result.append(f"{current_char}{count}")

    return "".join(result)

def balanced(s):
    stack = []
    mapping = {')': '(', ']': '[', '}': '{'} # Map closing to expected opening

    for char in s:
        if char in "([{":
            stack.append(char)
        elif char in ")]}":
            if not stack or stack.pop() != mapping[char]:
                return False

    return len(stack) == 0

def merge(a, b):
    i = 0 # Pointer for a
    j = 0 # Pointer for b
    merged_list = []

    while i < len(a) and j < len(b):
        if a[i] <= b[j]:
            merged_list.append(a[i])
            i += 1
        else:
            merged_list.append(b[j])
            j += 1

    # Append remaining elements from either list
    while i < len(a):
        merged_list.append(a[i])
        i += 1

    while j < len(b):
        merged_list.append(b[j])
        j += 1

    return merged_list

def to_base(n, b):
    if n == 0:
        return "0"

    digits = []
    while n > 0:
        remainder = n % b
        # Map value to character (0-9 then a-f)
        digit_char = str(remainder) if remainder < 10 else chr(ord('a') + remainder - 10)
        digits.append(digit_char)

        n //= b

    return "".join(reversed(digits))
